class Solution {
public:
    int m, n;
    void dfs(vector<vector<char>>& b, int i, int j) {
        if (i < 0 || i >= m || j < 0 || j >= n || b[i][j] != 'X') return;
        b[i][j] = '.';
        dfs(b, i + 1, j);
        dfs(b, i - 1, j);
        dfs(b, i, j + 1);
        dfs(b, i, j - 1);
    }
    int countBattleships(vector<vector<char>>& board) {
        m = board.size(); n = board[0].size();
        int cnt = 0;
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (board[i][j] == 'X') { cnt++; dfs(board, i, j); }
        return cnt;
    }
};

