class Solution {
    public int countBattleships(char[][] board) {
        int m = board.length, n = board[0].length, cnt = 0;
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (board[i][j] == 'X') { cnt++; dfs(board, i, j); }
        return cnt;
    }
    private void dfs(char[][] b, int i, int j) {
        if (i < 0 || i >= b.length || j < 0 || j >= b[0].length || b[i][j] != 'X') return;
        b[i][j] = '.';
        dfs(b, i + 1, j);
        dfs(b, i - 1, j);
        dfs(b, i, j + 1);
        dfs(b, i, j - 1);
    }
}

