    const m = board.length, n = board[0].length;
    function dfs(i, j) {
        if (i < 0 || i >= m || j < 0 || j >= n || board[i][j] !== 'X') return;
        board[i][j] = '.';
        dfs(i + 1, j); dfs(i - 1, j); dfs(i, j + 1); dfs(i, j - 1);
    }
    let cnt = 0;
    for (let i = 0; i < m; i++)
        for (let j = 0; j < n; j++)
            if (board[i][j] === 'X') { cnt++; dfs(i, j); }
    return cnt;
};

